source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    # The full line of 2s is the wall; all pieces move toward it.
    wall = None
    for r, row in enumerate(g):
        if all(v == 2 for v in row):
            wall = ("row", r)
            break
    if wall is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                wall = ("col", c)
                break
    if wall is None:
        return g
    kind, pos = wall
    dr = -1 if kind == "row" and pos == 0 else (1 if kind == "row" else 0)
    dc = -1 if kind == "col" and pos == 0 else (1 if kind == "col" else 0)
    # A wall at the far edge determines direction toward that edge.
    if kind == "row" and pos == h - 1: dr = 1
    if kind == "row" and pos == 0: dr = -1
    if kind == "col" and pos == w - 1: dc = 1
    if kind == "col" and pos == 0: dc = -1
    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and g[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            pieces.append((color, cells))
    if dr < 0: pieces.sort(key=lambda p: min(r for r,c in p[1]))
    elif dr > 0: pieces.sort(key=lambda p: -max(r for r,c in p[1]))
    elif dc < 0: pieces.sort(key=lambda p: min(c for r,c in p[1]))
    elif dc > 0: pieces.sort(key=lambda p: -max(c for r,c in p[1]))
    occupied = {(r,c) for r in range(h) for c in range(w) if g[r][c] == 2}
    for color, cells in pieces:
        occupied.update(cells)
    moved = []
    for color, cells in pieces:
        for cell in cells: occupied.remove(cell)
        shift = 0
        while True:
            nxt = [(r + dr*(shift+1), c + dc*(shift+1)) for r,c in cells]
            if any(r < 0 or r >= h or c < 0 or c >= w or (r,c) in occupied for r,c in nxt):
                break
            shift += 1
        final = [(r + dr*shift, c + dc*shift) for r,c in cells]
        occupied.update(final)
        moved.append((color, final))
    out = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 2: out[r][c] = 2
    for color, cells in moved:
        for r,c in cells: out[r][c] = color
    return out
'''
